VH=28 FOV=0.7 K=32/FOV VEL=0.07 GIRO=0.075 TAP=4 VELE=0.035 PRESUP=1400 floor,abs,sqrt,byte=math.floor,math.abs,math.sqrt,string.byte NIVELES={"################################".."#P.....#.........#.............#".."#......#....e....#....a....e...#".."#......D.........D.............#".."#..h...#.........#.............#".."####D###.........#######D#######".."#......#...e.....#.............#".."#......#####D#####..e......h...#".."#..e...#.........#.............#".."#......#..M...M..#.............#".."#..a...#.........#######L#######".."#......D....k....#.............#".."#......#..M...M..#..e.......e..X".."#..e...#....e....#.............#".."#......#.........#....a........#".."################################","MMMMMMMMMMMMMMMMMMMMMMMMMMMMMMMM".."M.........M.....e.....M........M".."M..P......D...........D...e..a.M".."M.........M.....h.....M........M".."MMMMDMMMMMMMMMMMDMMMMMMMMMMDMMMM".."#......#..............#........#".."#..e...#..#..#..#..#..#...e....#".."#......D..............D........#".."#..a...#..#..#..#..#..#........#".."#......#......e.......#...h....#".."####D###########L###############".."#..............#...............#".."#..e....h......#....e.....e....X".."#..............#...............#".."#......k.......#....a....e.....#".."################################",}TBASE={[35]=0,[77]=128,[68]=256,[76]=256,[88]=384}TIPOS={e=1,h=2,a=3,k=4}CODIGO={[32]=0,[107]=1,[46]=2,[58]=3,[43]=4,[35]=5,[64]=6}CT={0,3,7,11,14,16}DEMONIO={"    k      k    ","   k+k    k+k   ","   k++kkkk++k   ","    k######k    ","   k#@k##k@#k   ","   k########k   ","   k##kkkk##k   ","    kk#..#kk    ","  kk::kkkk::kk  "," k::::####::::k "," k:k::####::k:k "," k:kk:####:kk:k ","  k  k::::k  k  ","    k::kk::k    ","    k::k k::k   ","   kkkk   kkk   ",}POSES={{},{[15]="   k::k k::k    ",[16]="   kkk   kkkk   "},{[7]="   k##k@@k##k   ",[8]=" @@ kk#..#kk @@ ",[9]="k@@kk:kkkk:kk@@k",[11]="  k ::####:: k  ",[12]="    k:####:k    ",[13]="     k::::k     ",[16]="   kkkk   kkkk  "},{[12]="   kk      kk   ",[13]="  k+:kkkkkk:+k  ",[14]=" k::::#..#::::k ",[15]="k:k@k######k@k:k",[16]="kkkkkkkkkkkkkkkk"},}OBJETOS={"kkkkkkkk","k@@@@@@k","k@@kk@@k","k@kkkk@k","k@kkkk@k","k@@kk@@k","k@@@@@@k","kkkkkkkk","        "," k k k  ","k#k#k#k ","k#k#k#k ","kkkkkkkk","k::::::k","k::::::k","kkkkkkkk","  kkk   "," k@@@k  "," k@k@k  "," k@@@k  ","  k@k   ","  k@kk  ","  k@@k  ","  kkk   ",}ARMA={"      ####      ","      #..#      ","      #..#      ","     ##..##     ","     #....#     ","    ##....##    ","   #..####..#   ","  #..#....#..#  ","  #.#......#.#  "," #..#......#..# "," #..#......#..# ","#...#......#...#",}FOGON={"  #  #  "," # ## # ","  ####  ","########","  ####  "," # ## # ","  #  #  "}CORAZON={".#.#.","#####","#####",".###.","..#.."}BALA={".#.","###","###","###","###"}LLAVE={"###..","#.###","###.#"}function _init()F,W,DO,SEEN={},{},{},{}for i=1,VH*32 do F[i]=0 end for i=1,256 do W[i]=0 end for i=1,16 do SEEN[i]=0 end ZB,CX,VI,VD={},{},{},{}for c=1,64 do CX[c]=2*(c-0.5)/64-1 end PF={}for y=1,VH do local v=(y<5)and 1 or((y>14)and floor((y-14)/2)+1 or 0)PF[y]=v*33 end SHT,SH5={},{}for s=0,7 do local t,t5={},{}for v=0,16 do t[v]=floor(v*(1-s*0.11)+0.5)t5[v]=t[v]<<5 end SHT[s+1],SH5[s+1]=t,t5 end local B={0,8,2,10,12,4,14,6,3,11,1,9,15,7,13,5}BT={}for py=0,1 do for px=0,1 do local ta,tb={},{}for v=0,16 do local function on(i,j)return(v>B[(2*py+j)*4+2*px+i+1])and 1 or 0 end ta[v]=on(0,0)*2+on(1,0)tb[v]=on(0,1)*2+on(1,1)end BT[py*4+px*2+1],BT[py*4+px*2+2]=ta,tb end end TX={}for y=0,7 do for x=0,15 do local r=((x*7+y*13)*37)%5 local v=8+r if y%4==0 or(y<4 and x==0)or(y>4 and x==8)then v=2 end TX[y*16+x+1]=v v=9 if x==0 or y==0 then v=13 end if x==15 or y==7 then v=5 end if(x==2 or x==13)and(y==2 or y==5)then v=16 end TX[128+y*16+x+1]=v v=(x%4==0)and 3 or 8 if y==3 or y==4 then v=12 end if x==12 and y==4 then v=16 end TX[256+y*16+x+1]=v v=(((x+y)>>1)&1==0)and 16 or 2 if y==0 or y==7 then v=6 end TX[384+y*16+x+1]=v end end IMG,EXT={},{}for i=1,152 do IMG[i]=0 end for i=1,88 do EXT[i]=255 end local function guardar(fila,w0,r,e0)for u=0,#fila-1 do local c=CODIGO[byte(fila,u+1)]local w=w0+(u>>3)IMG[w]=IMG[w]|(c<<((u&7)*3))if c>0 then local e=EXT[e0+u]local top,bot=e&255,e>>8 if r<top then top=r end if r>bot then bot=r end EXT[e0+u]=top|(bot<<8)end end end for f=0,3 do for r=1,16 do local fila=POSES[f+1][r]or((f==3)and""or DEMONIO[r])guardar(fila,f*32+(r-1)*2+1,r-1,f*16+1)end end for k=0,2 do for r=1,8 do guardar(OBJETOS[k*8+r],129+k*8+r-1,r-1,65+k*8)end end DEMONIO,POSES,OBJETOS=nil,nil,nil ARMAM={}for i,f in ipairs(ARMA)do ARMAM[i]=f:gsub("%.","#")end OX,OY,OK,OH,OS,OT,OC,OL,PSX,PDP,PW={},{},{},{},{},{},{},{},{},{},{}fr,ha,hb,acorde=0,0,0,false maxn=dget(0)or 0 estado="titulo"end function cargar(n)lvl=n local s=NIVELES[n]MS=s:gsub("[Pehak]",".")for k in pairs(DO)do DO[k]=nil end for i=1,16 do SEEN[i]=0 end NO,NE=0,0 PUERTAS={}for i=1,512 do local ch=s:sub(i,i)local x,y=(i-1)%32+0.5,(i-1)//32+0.5 if ch=="P"then px,py,ang=x,y,0 end if ch=="D"or ch=="L"then DO[i]=0 PUERTAS[#PUERTAS+1]=i end local tipo=TIPOS[ch]if tipo then NO=NO+1 OX[NO],OY[NO],OK[NO]=x,y,tipo OH[NO]=(tipo==1)and 3 or 1 OS[NO],OT[NO],OC[NO],OL[NO],PDP[NO]=0,0,60,false,0 if tipo==1 then NE=NE+1 end end end vida,balas,llave,bajas=100,30,false,0 DX,DY=math.cos(ang),math.sin(ang)caminar,mapa=true,false cool,fogon,dano,msgt=0,0,0,0 t0=fr hudok=false estado="juego"end function aviso(s)msg,msgt=s,60 end function libre(x,y)local i=floor(y)*32+floor(x)+1 local c=byte(MS,i)if c==46 then return true end if c==68 or c==76 then return DO[i]>=14 end return false end function vista(x0,y0,x1,y1)local dx,dy=x1-x0,y1-y0 local n=floor(sqrt(dx*dx+dy*dy)*3)+1 dx,dy=dx/n,dy/n for k=1,n-1 do x0,y0=x0+dx,y0+dy if not libre(x0,y0)then return false end end return true end function entrada()local a,b=btn("a"),btn("b")if a then ha=ha+1 end if b then hb=hb+1 end if a and b then acorde=true end if acorde then if not a and not b then if ha<10 and hb<10 then mapa=not mapa end acorde,ha,hb=false,0,0 end return 0 end local g=0 if a then g=(ha<TAP)and-GIRO/4 or-GIRO end if b then g=(hb<TAP)and GIRO/4 or GIRO end if not a and ha>0 then if ha<TAP then g=g+GIRO/4*ha if mapa then mapa=false else caminar=not caminar end end ha=0 end if not b and hb>0 then if hb<TAP then g=g-GIRO/4*hb if mapa then mapa=false else disparar()end end hb=0 end return g end function disparar()if cool>0 then return end if balas<=0 then aviso("Sin balas")return end balas,cool,fogon,hudok=balas-1,9,3,false for i=1,NO do if OK[i]==1 and OH[i]>0 and abs(OX[i]-px)+abs(OY[i]-py)<10 then if OS[i]==0 then OS[i]=1 end end end local mejor,md=0,ZB[32]for i=1,NO do local d=PDP[i]if OK[i]==1 and OH[i]>0 and d>0 and d<md and abs(PSX[i]-32)<=PW[i]/3+1.5 then mejor,md=i,d end end if mejor>0 then local i=mejor OH[i]=OH[i]-1 if OH[i]<=0 then OS[i],bajas,hudok=3,bajas+1,false else OS[i],OT[i]=1,0 OC[i]=OC[i]+15 end end end function mover()if not caminar then return end local dx,dy=DX*VEL,DY*VEL local r=0.25 local nx=px+dx local sx=(dx>0)and r or-r if libre(nx+sx,py-r)and libre(nx+sx,py+r)then px=nx else tocar(nx+sx,py)end local ny=py+dy local sy=(dy>0)and r or-r if libre(px-r,ny+sy)and libre(px+r,ny+sy)then py=ny else tocar(px,ny+sy)end end function tocar(x,y)if byte(MS,floor(y)*32+floor(x)+1)==88 then fin_nivel()end end function puertas()for _,i in ipairs(PUERTAS)do local x,y=(i-1)%32+0.5,(i-1)//32+0.5 if abs(px-x)<1.6 and abs(py-y)<1.6 then if byte(MS,i)==76 and not llave then if msgt==0 then aviso("Necesitas la llave")end elseif DO[i]<16 then DO[i]=DO[i]+1 end end end end function objetos()for i=1,NO do local k=OK[i]if k>1 and OH[i]>0 and abs(OX[i]-px)<0.6 and abs(OY[i]-py)<0.6 then if k==2 and vida<100 then vida,OH[i]=math.min(100,vida+25),0 aviso("Salud +25")elseif k==3 then balas,OH[i]=balas+10,0 aviso("Balas +10")elseif k==4 then llave,OH[i]=true,0 aviso("Tienes la llave")end hudok=false end end end function enemigos()for i=1,NO do if OK[i]==1 and OH[i]>0 then local dx,dy=px-OX[i],py-OY[i]local d=sqrt(dx*dx+dy*dy)if(fr+i)%8==0 then OL[i]=d<12 and vista(OX[i],OY[i],px,py)end local s=OS[i]if s==0 then if OL[i]then OS[i]=1 end elseif s==1 then if d>1.3 then local mx,my=dx/d*VELE,dy/d*VELE local nx,ny=OX[i]+mx,OY[i]+my if libre(nx+(mx>0 and 0.3 or-0.3),OY[i])then OX[i]=nx end if libre(OX[i],ny+(my>0 and 0.3 or-0.3))then OY[i]=ny end end OC[i]=OC[i]-1 if OC[i]<=0 and OL[i]and d<10 then OS[i],OT[i]=2,18 end elseif s==2 then OT[i]=OT[i]-1 if OT[i]==9 and OL[i]and rnd(1)<0.8-d*0.06 then vida,dano,hudok=vida-4-flr(rnd(8)),4,false if vida<=0 then vida,estado,timer=0,"muerto",60 end end if OT[i]<=0 then OS[i],OC[i]=1,40+flr(rnd(50))end end end end end function fin_nivel()local seg=(fr-t0)//30 t1="Tiempo "..(seg//60)..":"..string.format("%02d",seg%60)t2="Bajas "..bajas.." de "..NE t3=""local b=dget(lvl)or 0 if b==0 or seg<b then dset(lvl,seg)if b>0 then t3="¡Récord!"end else t3="Mejor "..(b//60)..":"..string.format("%02d",b%60)end if lvl>maxn then maxn=lvl dset(0,lvl)end estado,timer=(lvl<#NIVELES)and"nivel"or"victoria",30 end function _update()fr=fr+1 if estado=="titulo"then if btnp("a")or btnp("b")then cargar(1)end elseif estado=="juego"then local g=entrada()if mapa then return end ang=ang+g DX,DY=math.cos(ang),math.sin(ang)if cool>0 then cool=cool-1 end if fogon>0 then fogon=fogon-1 end if dano>0 then dano=dano-1 end if msgt>0 then msgt=msgt-1 end mover()if estado~="juego"then return end puertas()objetos()enemigos()else if timer>0 then timer=timer-1 elseif btnp("a")or btnp("b")then if estado=="muerto"then cargar(lvl)elseif estado=="nivel"then cargar(lvl+1)else estado="titulo"end end end end function paredes()local F,MS,DO,TX,ZB,CX,SEEN,TBASE=F,MS,DO,TX,ZB,CX,SEEN,TBASE local floor,abs,byte,VH,K=floor,abs,byte,VH,K local i=1 for y=1,VH do local v=PF[y]for k=i,i+31 do F[k]=v end i=i+32 end local px,py,dx,dy=px,py,DX,DY local plx,ply=-dy*FOV,dx*FOV local fx,fy=floor(px),floor(py)for c=0,63 do local cx=CX[c+1]local rx,ry=dx+plx*cx,dy+ply*cx local ddx=(rx==0)and 1e9 or abs(1/rx)local ddy=(ry==0)and 1e9 or abs(1/ry)local sx,sy,sdx,sdy if rx<0 then sx,sdx=-1,(px-fx)*ddx else sx,sdx=1,(fx+1-px)*ddx end if ry<0 then sy,sdy=-32,(py-fy)*ddy else sy,sdy=32,(fy+1-py)*ddy end local side,dist,wx,cell local idx=fy*32+fx+1 while true do if sdx<sdy then sdx,idx,side=sdx+ddx,idx+sx,0 else sdy,idx,side=sdy+ddy,idx+sy,1 end cell=byte(MS,idx)if cell~=46 then if side==0 then dist=sdx-ddx wx=py+dist*ry else dist=sdy-ddy wx=px+dist*rx end wx=floor((wx-floor(wx))*16)if cell~=68 and cell~=76 then break end local o=DO[idx]if wx>=o then wx=wx-o break end end end local k=idx-1 SEEN[(k>>5)+1]=SEEN[(k>>5)+1]|(1<<(k&31))if dist<0.05 then dist=0.05 end ZB[c+1]=dist local s=floor(dist*1.3)+side+((cell==76)and 2 or 0)if s>7 then s=7 end local impar=c&1==1 local kp=impar and 31 or 992 local st=impar and SH5[s+1]or SHT[s+1]local lh=floor(K/dist)if lh<1 then lh=1 end local top=(VH-lh)//2 local step=2048//lh local ty,y0,y1=0,top,top+lh-1 if y0<0 then ty,y0=-y0*step,0 end if y1>VH-1 then y1=VH-1 end local tb=TBASE[cell]+wx+1 local i=y0*32+(c>>1)+1 for y=y0,y1 do F[i]=(F[i]&kp)|st[TX[tb+((ty>>4)&0x70)]]ty,i=ty+step,i+32 end end end function figuras()local F,ZB,IMG,EXT,CT,floor=F,ZB,IMG,EXT,CT,floor local dx,dy=DX,DY local plx,ply=-dy*FOV,dx*FOV local inv=1/(plx*dy-dx*ply)local n=0 for i=1,NO do PDP[i]=0 if OH[i]>0 or OK[i]==1 then local rx,ry=OX[i]-px,OY[i]-py local tx=inv*(dy*rx-dx*ry)local tz=inv*(-ply*rx+plx*ry)if tz>0.4 then local scx=32*(1+tx/tz)if scx>-20 and scx<84 then n=n+1 VI[n],VD[n],PSX[i],PDP[i]=i,tz,scx,tz end end end end for a=2,n do local i,d,b=VI[a],VD[a],a-1 while b>=1 and VD[b]<d do VI[b+1],VD[b+1],b=VI[b],VD[b],b-1 end VI[b+1],VD[b+1]=i,d end local suma,desde=0,1 for a=n,1,-1 do local h=K/VD[a]local lado=math.min(h,64)suma=suma+lado*math.min(h,VH)if suma>PRESUP and a<n then desde=a+1 break end end for a=1,desde-1 do PDP[VI[a]]=0 end for a=desde,n do local i,tz=VI[a],VD[a]local hs=K/tz local D,wpr,base,eb,sh=8,1,128+(OK[i]-2)*8,64+(OK[i]-2)*8,floor(hs*0.35)if OK[i]==1 then local f=0 if OS[i]==3 then f=3 elseif OS[i]==2 then f=2 elseif OS[i]==1 then f=(fr>>3)&1 end D,wpr,base,eb,sh=16,2,f*32,f*16,floor(hs*0.85)end PW[i]=sh if sh>=1 then local y1=floor(VH/2+hs/2)local y0=y1-sh+1 local x0=floor(PSX[i]-sh/2)local s=math.min(7,floor(tz*1.3))+1 local step=(D<<8)//sh for x=math.max(x0,0),math.min(x0+sh-1,63)do if tz<ZB[x+1]then local u=((x-x0)*step)>>8 local e=EXT[eb+u+1]local top,bot=e&255,e>>8 if top<=bot then local ya=math.max(0,y0+top*sh//D)local yb=math.min(VH-1,y1,y0+(bot+1)*sh//D)local impar=x&1==1 local kp=impar and 31 or 992 local st=impar and SH5[s]or SHT[s]local w0,cs=base+(u>>3)+1,(u&7)*3 local v,j=(ya-y0)*step,ya*32+(x>>1)+1 for y=ya,yb do local p=(IMG[w0+(v>>8)*wpr]>>cs)&7 if p>0 then F[j]=(F[j]&kp)|st[CT[p]]end v,j=v+step,j+32 end end end end end end end function empaquetar()local F,W=F,W local i,w=1,1 for ly=0,VH-1 do local b=(ly&1)*4 local ea,eb,oa,ob=BT[b+1],BT[b+2],BT[b+3],BT[b+4]for k=0,3 do local top,bot=0,0 for j=1,8 do local v=F[i]local p=v&31 top=(top<<2)|ea[p]bot=(bot<<2)|eb[p]v=v>>5 top=(top<<2)|oa[v]bot=(bot<<2)|ob[v]i=i+1 end W[w+k],W[w+4+k]=top,bot end w=w+8 end blit(W)end function marcador()if not hudok then hv,hb_,hk=tostring(vida),tostring(balas),"N"..lvl.." "..bajas.."/"..NE hudok=true end spr(CORAZON,1,58)print(hv,8,57)spr(BALA,34,58)print(hb_,39,57)if llave then spr(LLAVE,62,59)end print(hk,127-#hk*6,57)end function dibmapa()cls()for k=0,511 do if SEEN[(k>>5)+1]&(1<<(k&31))~=0 then local x,y=(k&31)*4,(k>>5)*3+4 local c=byte(MS,k+1)if c==68 or c==76 then rect(x,y,x+3,y+2)elseif c~=46 then rectfill(x,y,x+3,y+2)end end end if fr%16<10 then local x,y=px*4,py*3+4 rectfill(x-1,y-1,x+1,y+1)line(x,y,x+DX*5,y+DY*4)end print("MAPA",0,0)end function centrado(s,y,sz)sz=sz or 1 print(s,(128-utf8.len(s)*6*sz)//2,y,1,sz)end function _draw()if estado=="titulo"then cls()centrado("INFIERNO",2,2)centrado("A/B mantener: girar",22)centrado("A toque: andar/parar",31)centrado("B toque: disparar",40)centrado("A+B toque: mapa",49)return end if estado=="juego"and mapa then dibmapa()marcador()return end paredes()figuras()empaquetar()if estado=="juego"then local bx=caminar and floor(math.sin(fr*0.25)*3)or 0 local by=44+((cool>6)and 3 or 0)+(caminar and abs(bx)//2 or 0)spr(ARMAM,56+bx,by,0)spr(ARMA,56+bx,by,1)if fogon>0 then spr(FOGON,60+bx,by-7,1)end if dano>0 then rectfill(0,0,127,55,2)end if msgt>0 then local w=utf8.len(msg)*6+2 rectfill(63-w//2,0,64+w//2,9,0)centrado(msg,1)end end marcador()if estado~="juego"then rectfill(10,6,117,50,0)rect(10,6,117,50)if estado=="muerto"then centrado("HAS MUERTO",14)centrado("Pulsa para repetir",34)else centrado((estado=="nivel")and("NIVEL "..lvl.." SUPERADO")or"¡VICTORIA!",9)centrado(t1,20)centrado(t2,29)centrado(t3,38)end end end
